params.command:
$ErrorActionPreference='Stop'
$repo=Join-Path $env:USERPROFILE 'local-ai-workspaces\mhw-mods'
git -C $repo fetch origin --prune
$deleted=@(); $skipped=@()
function Delete-Guarded([string]$b,[string]$expected,[scriptblock]$guard){
  $line=(git -C $repo ls-remote origin ("refs/heads/"+$b))
  if(-not $line){$script:skipped += [pscustomobject]@{branch=$b;reason='already-absent'};return}
  $actual=($line -split '\s+')[0]
  if($actual -ne $expected){throw "tip changed for $b expected=$expected actual=$actual"}
  & $guard
  git -C $repo push origin --delete $b
  if($LASTEXITCODE -ne 0){throw "delete failed for $b"}
  $script:deleted += $b
}
Delete-Guarded 'fix/codex-quota-dispatch-circuit-20260929' '40d4454fd6f5eabda9650acb58246025daff5ecc' {
  $paths=@('tools/agent-control/README.md','tools/agent-control/lib/control-core.mjs','tools/agent-control/package.json','tools/agent-control/server.mjs','tools/agent-control/test/control-core.test.mjs')
  foreach($p in $paths){
    $a=(git -C $repo rev-parse ("origin/main:"+$p)).Trim()
    $c=(git -C $repo rev-parse ("origin/fix/codex-quota-dispatch-circuit-20260929:"+$p)).Trim()
    if($a -ne $c){throw "quota payload diverged at $p"}
  }
}
Delete-Guarded 'agent/bridge-uia-native-20260929' 'e52328aea7a2cfa26a63a35e07003c736c9c571a' {
  $worker=git -C $repo show 'origin/main:heaven-bridge/worker.py'
  $uia=git -C $repo show 'origin/main:heaven-bridge/uia.ps1'
  $readme=git -C $repo show 'origin/main:heaven-bridge/README.md'
  if(($worker -notmatch 'uia_tree') -or ($worker -notmatch 'uia_set_value')){throw 'main lacks worker-v4 UIA routes'}
  if(($uia -notmatch 'UIAutomation') -or ($readme -notmatch 'Semantic Windows UI Automation')){throw 'main lacks landed semantic UIA implementation/docs'}
}
Delete-Guarded 'agent-bridge' '30fcf1d6a4946aaa8f760ab9b5141453b6b87e69' {
  $worker=git -C $repo show 'origin/main:heaven-bridge/worker.py'
  $readme=git -C $repo show 'origin/main:heaven-bridge/README.md'
  if(($worker -notmatch 'chatgpt-heaven-bridge-v2') -or ($readme -notmatch 'canonical worker source')){throw 'canonical Python bridge proof missing'}
}
git -C $repo fetch origin --prune
[pscustomobject]@{deleted=$deleted;skipped=$skipped;main=(git -C $repo rev-parse origin/main).Trim()}|ConvertTo-Json -Depth 5 -Compress
